def main() -> None:
    parser = argparse.ArgumentParser(description="Quality Platform Lab commands")
    subparsers = parser.add_subparsers(dest="command", required=True)
    for name in ("migrate", "seed", "health", "verify"):
        subparsers.add_parser(name)
    snapshot_import = subparsers.add_parser(
        "snapshot-import",
        help="Preview or apply a UTF-8 CSV to the local snapshot table",
    )
    snapshot_import.add_argument("action", choices=("preview", "apply"))
    snapshot_import.add_argument("source", type=Path)
